// pass in a negative coils value to reverse direction...
float sdHelixSpiral(vec3 p, float rad1,float rad2, float height, float coils, float pd,float ph)
{
    float rounding = 0.1;
    float dir = sign(coils)*0.5;
    coils=abs(coils);

    coils =  coils / (height/PI);

    float vv = clamp(p.z, -height*0.5, height*0.5);
    vv = remap(vv,-height*0.5, height*0.5,rad2,rad1);
    vec3 pp = vec3(normalize(p.xy)*vv, p.z);
    float d1 = distance(p, pp);
	float d2 = asin(sin(p.z*coils + dir*atan(p.x,p.y)))/coils;
    float d=sdBox2D(vec2(d1,d2), vec2(pd,ph))-rounding;

    // hard clamp top and bottom
    float t = abs(p.z) - height*0.5;
    d = smax(d,t,0.5);
    return d;
}


